  // followed by a comma (mid-object) or preceded by one (last key).
  const surgical = text.replace(/(,)?\n[ \t]*"badges"[ \t]*:[ \t]*\{[^{}]*\}(,)?(?=\n)/, (m, before, after) => (before && after ? ',' : ''));
